document.querySelector("#batch40 .grid").insertAdjacentHTML("beforeend","<a class=\"card\" href=\"summaries/mahmoud-15455380.html\"><div class=\"book-art real-cover\"><img src=\"data:image/webp;base64,\" alt=\"غلاف عالم الأسرار\" width=\"270\" height=\"360\" loading=\"lazy\"></div><span class=\"tag\">مرجع طبعة · غير متاح حاليا</span><h3>عالم الأسرار</h3><p>تسرد نبذة عالم الأسرار موضوعات تمتد من أسئلة دينية ولغوية إلى النفس والبنوك والسياسة. يجمعها منظور مصطفى محمود التأملي، لكن اختلافها يقتضي اختلاف…</p><small>مصطفى محمود</small></a><a class=\"card\" href=\"summaries/mahmoud-15455401.html\"><div class=\"book-art real-cover\"><img src=\"data:image/webp;base64,\" alt=\"غلاف هل هو عصر الجنون ؟\" width=\"270\" height=\"360\" loading=\"lazy\"></div><span class=\"tag\">مرجع طبعة · غير متاح حاليا</span><h3>هل هو عصر الجنون ؟</h3><p>تربط نبذة الطبعة السؤال في العنوان بتناقض السلوك والظواهر اليومية. نقرأ كلمة الجنون هنا بوصفها تعبيرا جدليا في عنوان كتاب مقالات، لا تشخيصا لمرض …</p><small>مصطفى محمود</small></a><a class=\"card\" href=\"summaries/mahmoud-15455384.html\"><div class=\"book-art real-cover\"><img src=\"data:image/webp;base64,\" alt=\"غلاف على حافة الانتحار\" width=\"270\" height=\"360\" loading=\"lazy\"></div><span class=\"tag\">مرجع طبعة · غير متاح حاليا</span><h3>على حافة الانتحار</h3><p>تضع نبذة الطبعة على حافة الانتحار في السياسة والعلاقة بين الدين والصراعات الدولية. لذلك لا ينبغي اختياره بوصفه دليلا للصحة النفسية أو كتابا لعلاج…</p><small>مصطفى محمود</small></a>");
